<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';
import {request} from '@/services/api';
type Addresses={addresses:string[];recoveryUrls:string[];directory:Record<string,string>};
type Check={id:string;name:string;path:string;ok:boolean;status:number;detail:string;durationMs:number};
type Report={address:string;localPreview:boolean;connectionOK:boolean;contentOK:boolean;ok:boolean;checkedAt:string;checks:Check[]};
const primary=ref(''),backups=ref(''),recovery=ref(''),busy=ref(false),testing=ref(false),message=ref(''),error=ref(''),file=ref(''),saved=ref<string[]>([]),report=ref<Report|null>(null);
function fill(v:Addresses){primary.value=v.addresses[0]||'';backups.value=v.addresses.slice(1).join('\n');recovery.value=v.recoveryUrls.join('\n');saved.value=v.addresses;file.value=JSON.stringify(v.directory,null,2);report.value=null;}
onMounted(async()=>{try{fill(await request<Addresses>('/api/admin/service-addresses'));}catch(e){error.value=(e as Error).message;}});
watch([primary,backups,recovery],()=>{report.value=null;message.value='';},{flush:'sync'});
const lines=(v:string)=>v.split(/[\n,，]/).map(x=>x.trim()).filter(Boolean);
async function save(){busy.value=true;message.value='';error.value='';try{fill(await request<Addresses>('/api/admin/service-addresses','PUT',{addresses:[primary.value.trim(),...lines(backups.value)],recoveryUrls:lines(recovery.value)}));message.value='服务域名已保存，请检测接口后复制接入链接。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function test(address:string){if(testing.value||busy.value)return;testing.value=true;report.value=null;error.value='';try{report.value=await request<Report>('/api/admin/service-addresses/check','POST',{address});}catch(e){error.value=(e as Error).message;}finally{testing.value=false;}}
function copy(data:string){uni.setClipboardData({data});}
</script>
<template>
<view class="addresses">
 <view class="intro"><text class="title">连接运营服务</text><text class="hint">① 设置域名　② 测试真实接口　③ 复制链接到本地打包器</text></view>
 <view class="connection-box"><text class="eyebrow">接入链接 · 给打包器使用</text><text class="hint">链接由已保存域名生成，包含公开签名目录，不包含管理员密码。</text>
  <view v-for="(address,index) in saved" :key="address" class="saved-link"><view class="link-caption"><text>{{index===0?'主服务':'备用服务 '+index}}</text><text v-if="address.startsWith('http:')" class="warning">仅本机预览，正式打包需要 HTTPS</text></view><text class="url" selectable>{{address}}/api/service-directory</text><view class="actions"><button @click="copy(address+'/api/service-directory')">复制接入链接</button><button :disabled="testing||busy" @click="test(address)">{{testing?'检测中…':'测试此服务接口'}}</button></view></view>
 </view>
 <view class="settings"><text class="label">主域名</text><input v-model="primary" :disabled="busy||testing" placeholder="https://你的主域名"/><text class="label">备用域名（每行一个，最多4个）</text><textarea v-model="backups" :disabled="busy||testing" :maxlength="-1" placeholder="https://你的备用域名"/><text class="hint">先让域名指向当前服务并配置 HTTPS。检测不会保存；保存也不会自动判定可用。</text><view class="actions"><button class="save" :disabled="busy||testing" @click="save">{{busy?'保存中…':'保存服务域名'}}</button><button :disabled="busy||testing||!primary.trim()" @click="test(primary.trim())">{{testing?'正在请求真实接口…':'测试填写的主域名'}}</button></view></view>
 <view v-if="testing" class="test-progress">正在并行检查服务身份、签名目录、各端配置、分类及影片接口…</view>
 <view v-if="report" class="report"><view class="report-heading"><text class="title">接口检测结果</text><text :class="report.ok?'success':'warning'">{{report.ok?'接口检测通过':report.connectionOK?'服务已接通 · 内容未就绪':'接入检测未通过'}}</text></view><text class="hint" selectable>{{report.address}} · {{new Date(report.checkedAt).toLocaleString()}}</text><text v-if="report.localPreview" class="hint">这是本机检测结果，不能作为远程设备接入或正式打包验收。</text><view class="summary"><text :class="report.connectionOK?'success':'failure'">{{report.connectionOK?'✓':'×'}} 服务与接入协议</text><text :class="report.contentOK?'success':'failure'">{{report.contentOK?'✓':'×'}} 分类与影片接口</text></view>
 <view v-for="check in report.checks" :key="check.id" class="check"><text class="check-status" :class="check.ok?'success':'failure'">{{check.ok?'通过':'失败'}}</text><view class="check-body"><text class="check-name">{{check.name}}</text><text class="path" selectable>{{check.path}}</text><text class="hint">{{check.detail}}</text></view><text class="timing">{{check.status?'HTTP '+check.status:'未连接'}}<br/>{{check.durationMs}} ms</text></view><text class="hint">本次只验证列出的接口响应；会员、支付、播放权限及真机使用需要单独联调。</text></view>
 <details><summary>域名全部失效时的独立恢复设置</summary><text class="hint">提前将签名地址文件放到独立 HTTPS 地址，再填入下面并保存。恢复地址需在 App 打包时写入；更换域名后同步更新该文件。</text><textarea v-model="recovery" :disabled="busy||testing" :maxlength="-1" placeholder="https://独立站点/hetun-service.json"/><button :disabled="!file||busy" @click="copy(file)">复制已保存的签名地址文件</button><text class="hint">迁移服务器时保留 data/service-key.pem 与业务数据，供已有 App 校验服务身份。</text></details>
 <text v-if="message" class="success notice">{{message}}</text><text v-if="error" class="failure notice">{{error}}</text>
</view>
</template>
<style scoped>
.addresses{color:var(--studio-text,#e5eae4)}.title,.label,.hint,.eyebrow,.url,.check-name,.path,.notice{display:block}.title{font-size:17px;font-weight:650}.hint{font-size:12px;line-height:1.8;color:var(--studio-muted,#98a5b5);margin:8px 0}.eyebrow{font-size:13px;font-weight:600;color:var(--studio-link,#c4d99b)}.connection-box{padding:20px;margin:20px 0;border:1px solid var(--studio-border,#35415a);border-radius:12px;background:var(--studio-panel,#10181d)}.saved-link+.saved-link{border-top:1px solid var(--studio-border);padding-top:16px;margin-top:16px}.link-caption,.report-heading,.summary,.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.link-caption{font-size:12px;margin:10px 0}.url{font:13px/1.8 ui-monospace,monospace;overflow-wrap:anywhere;padding:12px;border-radius:7px;background:var(--studio-input,#172329)}.label{font-size:12px;margin:16px 0 8px}input,textarea{box-sizing:border-box;width:100%;border:1px solid var(--studio-border,#35415a);border-radius:8px;padding:10px;font-size:13px;color:inherit;background:var(--studio-input,#172329)}input{height:44px}textarea{height:84px}.actions{margin-top:12px}button{margin:0;padding:8px 14px;font-size:12px;line-height:1.8;background:var(--studio-action,#24372f);color:var(--studio-link,#c4d99b);border:1px solid var(--studio-border);border-radius:7px}button[disabled]{opacity:.5}.save{font-weight:600}.report{margin-top:24px;border:1px solid var(--studio-border);padding:20px;border-radius:12px}.report-heading{justify-content:space-between;font-size:12px}.summary{padding:12px 0;font-size:13px}.check{display:flex;align-items:flex-start;gap:14px;border-top:1px solid var(--studio-border);padding:14px 0}.check-status{font-size:11px;white-space:nowrap;padding-top:2px}.check-body{flex:1;min-width:0}.check-name{font-size:13px;font-weight:600}.path{font:11px/1.8 ui-monospace,monospace;overflow-wrap:anywhere;color:var(--studio-muted)}.check .hint{margin:3px 0 0}.timing{font-size:11px;text-align:right;line-height:1.8;color:var(--studio-muted);white-space:nowrap}.success{color:var(--studio-link,#9ecf9a)}.warning{color:#a87a30}.failure{color:#c45151}.notice{margin-top:15px;font-size:12px}details{margin-top:24px;font-size:12px}details>button{margin-top:12px}.test-progress{padding:18px;font-size:13px;color:var(--studio-link)}@media(max-width:650px){.connection-box,.report{padding:14px}.timing{font-size:10px}.check{gap:8px}}
</style>
